**ANSI C**

```c
#include <stdio.h>

#define ROWS 5
#define COLS 5

typedef char TBoard[ROWS][COLS];

TBoard c4grid;                     /* global Connect-Four grid */

/* ---- stand-in for the Board's file aligned.h (use the supplied file instead) ---- */
void empty_grid(TBoard A)
{
    int i, j;
    for (i = 0; i < ROWS; i++)
        for (j = 0; j < COLS; j++)
            A[i][j] = ' ';
}

int is_aligned(TBoard A)          /* 1 if four equal discs are aligned, else 0 */
{
    static const int dr[4] = {0, 1, 1, 1};
    static const int dc[4] = {1, 0, 1, -1};
    int i, j, k, n, r, c;

    for (i = 0; i < ROWS; i++) {
        for (j = 0; j < COLS; j++) {
            if (A[i][j] == ' ')
                continue;
            for (k = 0; k < 4; k++) {
                n = 1;
                r = i + dr[k];
                c = j + dc[k];
                while (n < 4 && r >= 0 && r < ROWS && c >= 0 && c < COLS
                       && A[r][c] == A[i][j]) {
                    n++;
                    r += dr[k];
                    c += dc[k];
                }
                if (n == 4)
                    return 1;
            }
        }
    }
    return 0;
}
/* ---- end of stand-in ---- */

void display_grid(TBoard A)
{
    int i, j;

    for (i = 0; i < ROWS; i++) {
        printf("%d ", i + 1);              /* row number on the left   */
        for (j = 0; j < COLS; j++)
            printf(" %c", A[i][j]);        /* 5 items per line         */
        printf("\n");
    }
    printf("  ");
    for (j = 1; j <= COLS; j++)
        printf(" %d", j);                  /* column numbers below     */
    printf("\n");
}

int drop_disc(TBoard A, int col, char disc)
{
    int done = 0, i = ROWS;

    if (col >= 1 && col <= COLS) {
        while (done != 1 && i > 0) {
            if (A[i - 1][col - 1] == ' ') {   /* C arrays start at 0 */
                A[i - 1][col - 1] = disc;
                done = 1;
            }
            i = i - 1;
        }
    } else {
        done = -1;
    }
    return done;
}

void play_game(void)
{
    int stop = 0, placed_discs = 0, player = 0;
    int col, done, aligned;
    char disc;

    empty_grid(c4grid);
    do {
        if (player % 2 == 0) {
            printf("Player1 (X), enter a column number (1-%d): ", COLS);
            scanf("%d", &col);
            disc = 'X';
        } else {
            printf("Player2 (O), enter a column number (1-%d): ", COLS);
            scanf("%d", &col);
            disc = 'O';
        }

        done = drop_disc(c4grid, col, disc);
        if (done == 1) {
            display_grid(c4grid);
            player = player + 1;
            placed_discs = placed_discs + 1;
        } else if (done == 0) {
            printf("Chosen column is full!\n");
        } else {
            printf("Invalid column number!\n");
        }

        aligned = is_aligned(c4grid);
        if (aligned == 1) {
            if (disc == 'X')
                printf("Game Over! Player1 wins.\n");
            else if (disc == 'O')
                printf("Game Over! Player2 wins.\n");
            else
                printf("Error: Unknown Player type %c!\n", disc);
            stop = 1;
        }
    } while (stop != 1 && placed_discs < ROWS * COLS);

    if (stop == 0)
        printf("Game Over! It's a tie!\n");
}

int main(void)
{
    empty_grid(c4grid);
    display_grid(c4grid);          /* show the empty grid       */
    play_game();                   /* two users play the game   */
    return 0;
}
```

**ISO Pascal**

```pascal
program FourInALine;

const
  ROWS = 5;
  COLS = 5;

type
  TBoard = array[1..ROWS, 1..COLS] of char;

var
  c4grid: TBoard;                       { global Connect-Four grid }

{ ---- stand-in for the Board's file aligned.pas (use the supplied file instead) ---- }
procedure empty_grid(var A: TBoard);
var
  i, j: integer;
begin
  for i := 1 to ROWS do
    for j := 1 to COLS do
      A[i, j] := ' '
end;

function is_aligned(var A: TBoard): integer;
var
  i, j, k, n, r, c, dr, dc, found: integer;
  going: boolean;
begin
  found := 0;
  for i := 1 to ROWS do
    for j := 1 to COLS do
      if A[i, j] <> ' ' then
        for k := 1 to 4 do
        begin
          case k of
            1: begin dr := 0; dc := 1 end;
            2: begin dr := 1; dc := 0 end;
            3: begin dr := 1; dc := 1 end;
            4: begin dr := 1; dc := -1 end
          end;
          n := 1;
          r := i + dr;
          c := j + dc;
          going := true;
          while going do
            if (n < 4) and (r >= 1) and (r <= ROWS) and (c >= 1) and (c <= COLS) then
            begin
              if A[r, c] = A[i, j] then
              begin
                n := n + 1;
                r := r + dr;
                c := c + dc
              end
              else
                going := false
            end
            else
              going := false;
          if n = 4 then
            found := 1
        end;
  is_aligned := found
end;
{ ---- end of stand-in ---- }

procedure display_grid(var A: TBoard);
var
  i, j: integer;
begin
  for i := 1 to ROWS do
  begin
    write(i:1, ' ');                    { row number on the left }
    for j := 1 to COLS do
      write(' ', A[i, j]);              { 5 items per line }
    writeln
  end;
  write('  ');
  for j := 1 to COLS do
    write(' ', j:1);                    { column numbers below }
  writeln
end;

function drop_disc(var A: TBoard; col: integer; disc: char): integer;
var
  done, i: integer;
begin
  done := 0;
  i := ROWS;
  if (col >= 1) and (col <= COLS) then
  begin
    while (done <> 1) and (i > 0) do
    begin
      if A[i, col] = ' ' then
      begin
        A[i, col] := disc;
        done := 1
      end;
      i := i - 1
    end
  end
  else
    done := -1;
  drop_disc := done
end;

procedure play_game;
var
  stop, placed_discs, player, col, done, aligned: integer;
  disc: char;
begin
  stop := 0;
  placed_discs := 0;
  player := 0;
  empty_grid(c4grid);
  repeat
    if player mod 2 = 0 then
    begin
      write('Player1 (X), enter a column number (1-', COLS:1, '): ');
      readln(col);
      disc := 'X'
    end
    else
    begin
      write('Player2 (O), enter a column number (1-', COLS:1, '): ');
      readln(col);
      disc := 'O'
    end;

    done := drop_disc(c4grid, col, disc);
    if done = 1 then
    begin
      display_grid(c4grid);
      player := player + 1;
      placed_discs := placed_discs + 1
    end
    else if done = 0 then
      writeln('Chosen column is full!')
    else
      writeln('Invalid column number!');

    aligned := is_aligned(c4grid);
    if aligned = 1 then
    begin
      if disc = 'X' then
        writeln('Game Over! Player1 wins.')
      else
        writeln('Game Over! Player2 wins.');
      stop := 1
    end
  until (stop = 1) or (placed_discs >= ROWS * COLS);

  if stop = 0 then
    writeln('Game Over! It''s a tie!')
end;

begin
  empty_grid(c4grid);
  display_grid(c4grid);
  play_game
end.
```

